package com.codequest;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/mission")
public class MissionServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{if(Auth.userId(q)==null){p.sendRedirect("login");return;}int id;try{id=Integer.parseInt(q.getParameter("id"));}catch(Exception e){p.sendRedirect("missions");return;}String body="";
  try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("SELECT * FROM missions WHERE id=?")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){if(r.next()){body="<div class='card'><span class='pill'>"+View.esc(r.getString("category"))+"</span><span class='pill'>"+View.esc(r.getString("difficulty"))+"</span><p>"+View.esc(r.getString("description"))+"</p><form method='post' action='submit'><input type='hidden' name='missionId' value='"+id+"'><label><input style='width:auto' type='radio' name='answer' value='"+View.esc(r.getString("option_a"))+"' required> "+View.esc(r.getString("option_a"))+"</label><label><input style='width:auto' type='radio' name='answer' value='"+View.esc(r.getString("option_b"))+"'> "+View.esc(r.getString("option_b"))+"</label><label><input style='width:auto' type='radio' name='answer' value='"+View.esc(r.getString("option_c"))+"'> "+View.esc(r.getString("option_c"))+"</label><label><input style='width:auto' type='radio' name='answer' value='"+View.esc(r.getString("option_d"))+"'> "+View.esc(r.getString("option_d"))+"</label><button>Submit answer</button></form></div>";}}}
  catch(Exception ex){throw new IOException(ex);}if(body.isEmpty())body="<p>Mission not found.</p><a href='missions'>Back to missions</a>";p.setContentType("text/html;charset=UTF-8");p.getWriter().print(View.page("Mission",body,q.getContextPath()));}
}